{
  "technical_and_design_decisions": [
    "For U1 (Java): Create a new contract instance per transaction to ensure thread-safety, accepting the performance overhead.",
    "For U1 (Node.js): Ensure transactional context is passed as the first parameter to chaincode functions, aligning with existing Node.js shim behavior.",
    "For U2/U3: Move protos/utils to a new top-level package 'protoutils', update all import paths, and maintain backward compatibility via aliases if needed.",
    "For U4: Backport Kafka health check commits from master to the 1.4 LTS branch, resolving any merge conflicts and running the existing test suite.",
    "For U5: Introduce a new chaincode invoke type 'query' (read-only) that only permits GetState operations. Update peer endorsement and validation logic to allow channel Readers to invoke this type.",
    "For U6: Add a new configuration parameter 'PEER_GOSSIP_EXTERNALENDPOINT_ADVERTISED' to specify an external hostname:port. Modify gossip protocol to advertise this endpoint in Service Discovery responses.",
    "For U7: Extend the existing operations service (HTTP server) on both peer and orderer with a GET /version endpoint returning version metadata from build information.",
    "For U8: Refactor all Go samples in fabric-samples to follow idiomatic Go practices (error handling, naming conventions, project structure)."
  ],
  "assumptions": [
    "The developer is familiar with the Hyperledger Fabric codebase and development environment.",
    "U2 and U3 are duplicate requirements; only one implementation effort is needed.",
    "Backporting Kafka health checks (U4) involves minimal conflicts and can be validated with existing tests.",
    "U5 access control changes are limited to peer endorsement/validation; orderer changes are not required.",
    "U6 changes only affect peer gossip and service discovery modules; no SDK changes are required.",
    "Operations service (U7) already exists on peer and orderer; adding a version endpoint is a small extension.",
    "Samples (U8) reside in the fabric-samples repository and are in scope for this increment.",
    "Each activity includes unit testing effort; integration testing and documentation are separate activities.",
    "Code review and integration effort is estimated as a separate activity covering all features."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement transactional context for Node.js chaincode shim",
      "activity_description": "Modify Node.js shim to pass transactional context as first parameter to chaincode functions; ensure compatibility with existing contracts.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement transactional context for Java chaincode shim",
      "activity_description": "Redesign Java shim to create a new contract instance per transaction for thread-safety; update base classes and test.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "Refactor protos packages: move protos/utils to protoutils",
      "activity_description": "Create new protoutils package, move utility code, update all import references across the codebase, adjust build scripts, and verify no regressions.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Backport Kafka health checks to Fabric 1.4 LTS",
      "activity_description": "Identify relevant commits on master, cherry-pick/backport to 1.4 branch, resolve conflicts, run test suite to ensure health checks work.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Design and implement read-only chaincode invoke type",
      "activity_description": "Define new invoke type 'query' in chaincode shim and peer; enforce read-only semantics (only GetState); update chaincode invocation path.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "Update endorsement and validation logic for read-only invoke",
      "activity_description": "Modify ACL checks in peer to allow channel Readers to invoke read-only chaincode; update validation logic to reject state changes in read-only transactions.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Add new configuration for peer external endpoint advertisement",
      "activity_description": "Define environment variable PEER_GOSSIP_EXTERNALENDPOINT_ADVERTISED; parse and validate in peer configuration; propagate to gossip module.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8",
      "activity_name": "Modify gossip and service discovery to advertise external endpoint",
      "activity_description": "Update gossip protocol to include the configured external endpoint in membership information; ensure service discovery returns this endpoint to SDK clients.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A9",
      "activity_name": "Add version endpoint to peer operations service",
      "activity_description": "Implement GET /version HTTP endpoint in peer's operations server; return version, commit, and build metadata.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "Add version endpoint to orderer operations service",
      "activity_description": "Implement GET /version HTTP endpoint in orderer's operations server; return version, commit, and build metadata.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A11",
      "activity_name": "Update Fabric samples to idiomatic Go",
      "activity_description": "Review and refactor all Go sample chaincode and applications in fabric-samples to follow Go best practices (error handling, naming, structure).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A12",
      "activity_name": "Write unit tests for all new features",
      "activity_description": "Develop unit tests covering each new feature (transactional context, protoutils, read-only invoke, external endpoint, version endpoints, samples).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A13",
      "activity_name": "Write and execute integration tests",
      "activity_description": "Create integration test scenarios for each user story; run in CI environment; verify end-to-end functionality.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A14",
      "activity_name": "Update documentation",
      "activity_description": "Update configuration reference, user guides, and developer documentation for new features (read-only invoke, external endpoint, version endpoint, protoutils).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A15",
      "activity_name": "Code review and integration",
      "activity_description": "Self-review of all changes, address review feedback, merge to target branches, ensure CI passes.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 53
  }
}

